import{_ as a,a0 as e,w as l,s,I as n,x as r,a1 as i,A as o,ao as P}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"iptraf：一個實用的TCP/UDP網絡監控工具 | LCTT x X-CMD","titleTemplate":false,"description":"iptraf：一個實用的TCP/UDP網絡監控工具 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"iptraf：一個實用的TCP/UDP網絡監控工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"iptraf：一個實用的TCP/UDP網絡監控工具 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150126 iptraf--A TCP or UDP Network Monitoring Utility","title":"iptraf：一個實用的TCP/UDP網絡監控工具","tag":"201505","desc":""},"relativePath":"201505/20150126 iptraf--A TCP or UDP Network Monitoring Utility.md","filePath":"[post].md"}'),d={name:"201505/20150126 iptraf--A TCP or UDP Network Monitoring Utility.md"};function u(f,t,g,m,T,C){const p=e("Link");return l(),s("div",null,[t[15]||(t[15]=n("h1",{id:"iptraf-一個實用的tcp-udp網絡監控工具",tabindex:"-1"},[r("iptraf：一個實用的TCP/UDP網絡監控工具 "),n("a",{class:"header-anchor",href:"#iptraf-一個實用的tcp-udp網絡監控工具","aria-label":"Permalink to “iptraf：一個實用的TCP/UDP網絡監控工具”"},"​")],-1)),n("p",null,[i(p,{href:"http://iptraf.seul.org/about.html"},{default:o(()=>[...t[0]||(t[0]=[r("iptraf",-1)])]),_:1}),t[1]||(t[1]=r("是一個基於ncurses的IP局域網監控器，用來生成包括TCP信息、UDP計數、ICMP和OSPF信息、以太網負載信息、節點狀態信息、IP校驗和錯誤等等統計數據。",-1))]),t[16]||(t[16]=P(`<p>它基於ncurses的用户界面可以使用户免於記憶繁瑣的命令列開關。</p><h3 id="特徵" tabindex="-1">特徵 <a class="header-anchor" href="#特徵" aria-label="Permalink to “特徵”">​</a></h3><ul><li>IP流量監控器，用來顯示你的網絡中的IP流量變化信息。包括TCP標識信息、包以及字節計數，ICMP細節，OSPF包類型。</li><li>簡單的和詳細的接口統計數據，包括IP、TCP、UDP、ICMP、非IP以及其他的IP包計數、IP校驗和錯誤，接口活動、包大小計數。</li><li>TCP和UDP服務監控器，能夠顯示常見的TCP和UDP應用端口上發送的和接收的包的數量。</li><li>局域網數據統計模組，能夠發現在線的主機，並顯示其上的數據活動統計信息。</li><li>TCP、UDP、及其他協議的顯示過濾器，允許你只查看感興趣的流量。</li><li>日誌功能。</li><li>支持以太網、FDDI、ISDN、SLIP、PPP以及本地迴環接口類型。</li><li>利用Linux內核內置的原始套接字接口，允許它（指iptraf）能夠用於各種支持的網卡上</li><li>全屏，菜單式驅動的操作。</li></ul><p>###安裝方法###</p><p><strong>Ubuntu以及其衍生版本</strong></p><pre><code>sudo apt-get install iptraf
</code></pre><p><strong>Arch Linux以及其衍生版本</strong></p><pre><code>sudo pacman -S iptra
</code></pre><p><strong>Fedora以及其衍生版本</strong></p><pre><code>sudo yum install iptraf
</code></pre><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>如果不加任何命令列選項地運行<strong>iptraf</strong>命令，程序將進入一種交互模式，通過主菜單可以訪問多種功能。</p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/iptraf_1.png" alt=""></p><p>簡易的上手導航菜單。</p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/iptraf_2.png" alt=""></p><p>選擇要監控的接口。</p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/iptraf_3.png" alt=""></p><p>接口<strong>ppp0</strong>處的流量。</p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/iptraf_4.png" alt=""></p><p>試試吧！</p><hr>`,21)),n("p",null,[t[3]||(t[3]=r("via: ",-1)),i(p,{href:"http://www.unixmen.com/iptraf-tcpudp-network-monitoring-utility/"},{default:o(()=>[...t[2]||(t[2]=[r("http://www.unixmen.com/iptraf-tcpudp-network-monitoring-utility/",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=r("作者：",-1)),i(p,{href:"http://www.unixmen.com/author/seth/"},{default:o(()=>[...t[4]||(t[4]=[r("Enock Seth Nyamador",-1)])]),_:1}),t[8]||(t[8]=r(" 譯者：",-1)),i(p,{href:"https://github.com/DongShuaike"},{default:o(()=>[...t[5]||(t[5]=[r("DongShuaike",-1)])]),_:1}),t[9]||(t[9]=r(" 校對：",-1)),i(p,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[r("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=r("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[r("LCTT",-1)])]),_:1}),t[13]||(t[13]=r(" 原創翻譯，",-1)),i(p,{href:"http://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[r("Linux中國",-1)])]),_:1}),t[14]||(t[14]=r(" 榮譽推出",-1))])])}const U=a(d,[["render",u]]);export{x as __pageData,U as default};
